\set ON_ERROR_STOP on
BEGIN READ ONLY;
SELECT jsonb_build_object('cluster',(SELECT system_identifier::text FROM pg_control_system()),'server_version_num',current_setting('server_version_num'),'database_owner',(SELECT pg_get_userbyid(datdba) FROM pg_database WHERE datname=current_database()),'role_memberships',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT roleid::regrole::text role,member::regrole::text member,admin_option,inherit_option,set_option FROM pg_auth_members WHERE roleid IN (SELECT oid FROM pg_roles WHERE rolname LIKE 'capstone%') OR member IN (SELECT oid FROM pg_roles WHERE rolname LIKE 'capstone%')) x),'custom_types',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT t.typname,t.typtype,format_type(t.typbasetype,t.typtypmod) base_type,t.typnotnull FROM pg_type t WHERE t.typnamespace='public'::regnamespace AND t.typtype IN ('d','e','r','m')) x),'foreign_servers',(SELECT count(*) FROM pg_foreign_server),'large_objects',(SELECT count(*) FROM pg_largeobject_metadata),'partitions',(SELECT count(*) FROM pg_partitioned_table WHERE partrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)));
SELECT jsonb_build_object('database_privileges',jsonb_agg(to_jsonb(x))) FROM (SELECT rolname,has_database_privilege(rolname,current_database(),'CONNECT') connect,has_database_privilege(rolname,current_database(),'CREATE') create_schema,has_database_privilege(rolname,current_database(),'TEMP') temporary,has_schema_privilege(rolname,'public','USAGE') schema_usage,has_schema_privilege(rolname,'public','CREATE') schema_create FROM pg_roles WHERE rolname=current_user OR rolname LIKE 'capstone%') x;
COMMIT;
